/**
 * Toast. A raised slab with a status LED: lit when active, dim cream when
 * neutral. Composes var(--echo-*).
 *
 * The slab is the chassis plastic, the same as the Select's sheet and the
 * caps: a darkened, translucent WELL (the old recipe) read as a brown-red
 * pane from nowhere in the system once it sat over anything warm.
 */
.echo-toast {
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--echo-space-6);
  overflow: hidden;
  /*
   * `min-width: 260px` is a floor, so it overflowed a narrower
   * container outright (294 > 284 on the docs page). A toast still wants to
   * be wide when there is room; `min()` gives it that without the floor.
   */
  min-width: min(260px, 100%);
  /* `min-width: 100%` plus 32px of padding overflows without this. */
  box-sizing: border-box;
  padding: var(--echo-space-6) var(--echo-space-8);
  border-radius: var(--echo-radius-xl);
  border: 0;
  background: linear-gradient(180deg, var(--echo-cap) 0%, var(--echo-cap-shadow) 100%);
  box-shadow: var(
    --echo-shadow-toast,
    inset 0 1.5px 0 rgb(255 255 255 / calc(0.28 * var(--echo-gloss, 1))),
    inset 0 0 0 1px color-mix(in oklab, var(--echo-seam) 70%, transparent),
    0 18px 36px -14px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.75 * var(--echo-shade, 1) * 100%), transparent)
  );
}

.echo-toast__led {
  display: inline-block;
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: 50%;
  background: color-mix(in oklab, var(--echo-text) 40%, transparent);
}

/* Active: the library's one lit accent, light kept inside the LED. */
/*
 * `active` lights the LED. Everything else (`info`) leaves it dark — the
 * value used to be spelled `"default"`.
 */
.echo-toast[data-tone="active"] .echo-toast__led {
  background: linear-gradient(
    180deg,
    var(--echo-primary-cap-top) 0%,
    var(--echo-primary-cap-mid) 45%,
    var(--echo-primary-cap-base) 100%
  );
  box-shadow: var(--echo-shadow-edge, inset 0 1px 0 rgb(255 255 255 / calc(0.4 * var(--echo-gloss, 1))));
}

.echo-toast__text {
  display: flex;
  flex-direction: column;
}

.echo-toast__title {
  /* In the toaster these are Base UI's h2 and p: no browser margins (BUG-82). */
  margin: 0;
  /* Long content wraps rather than pushing its container open. */
  overflow-wrap: anywhere;
  font-size: var(--echo-text-sm);
  font-weight: var(--echo-weight-semibold, 600);
  color: var(--echo-text);
}

.echo-toast__body {
  margin: 0;
  /* Long content wraps rather than pushing the slab open. */
  overflow-wrap: anywhere;
  font-size: var(--echo-text-xs);
  color: var(--echo-text-dim);
}

/* --- the toaster ---------------------------------------------------------- */

/*
 * One stack in the bottom corner at the inline end, above dialogs (the toast
 * layer). The viewport is on the page from the start, so what arrives in it
 * is announced.
 *
 * The toasts pile like ThrowStack's cards: the newest in front (last in the
 * DOM, so it paints on top), each one
 * behind 12px up and 5% smaller, showing only its edge. Pointer or focus on
 * the pile fans it into a column (Base UI's `data-expanded`, which also
 * pauses the timers), so every toast can be read and reached.
 */
.echo-toaster {
  --toast-gap: var(--echo-space-4);
  --toast-peek: 12px;
  position: fixed;
  inset-inline-end: clamp(1rem, 3vw, 2rem);
  bottom: clamp(1rem, 3vw, 2rem);
  z-index: var(--echo-z-toast, 400);
  width: min(360px, calc(100vw - 2rem));
  outline: none;
}

/* A toast pops up into place on a spring — solid quickly, overshooting a
   touch and settling — and leaves quickly and plainly. */
.echo-toaster .echo-toast {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  transform-origin: 50% 100%;
  transform: translateY(calc(var(--toast-index, 0) * -1 * var(--toast-peek)))
    scale(calc(1 - var(--toast-index, 0) * 0.05));
  transition:
    opacity var(--echo-duration-swap) ease,
    transform var(--echo-duration-pop) var(--echo-ease-pop),
    rotate var(--echo-duration-pop) var(--echo-ease-pop),
    height var(--echo-duration-pop) var(--echo-ease-pop);
}
/* Behind the front one, only the slab's edge shows. */
.echo-toaster .echo-toast[data-behind]:not([data-expanded]) {
  height: var(--toast-frontmost-height, auto);
}
.echo-toaster .echo-toast > * {
  transition: opacity var(--echo-duration-swap) ease;
}
.echo-toaster .echo-toast[data-behind]:not([data-expanded]) > * {
  opacity: 0;
}
/* Fanned: a column, newest at the bottom. */
.echo-toaster .echo-toast[data-expanded] {
  overflow: visible;
  transform: translateY(calc(-1 * var(--toast-offset-y, 0px) - var(--toast-index, 0) * var(--toast-gap)));
}
/* Bridges the gap below each one, so moving between toasts keeps it fanned. */
.echo-toaster .echo-toast[data-expanded]::after {
  content: "";
  position: absolute;
  inset-inline: 0;
  top: 100%;
  height: calc(var(--toast-gap) + 1px);
}
.echo-toaster .echo-toast[data-starting-style] {
  opacity: 0;
  transform: translateY(18px) scale(0.92);
}
.echo-toaster .echo-toast[data-ending-style] {
  opacity: 0;
  transform: translateY(8px) scale(0.97);
  transition-duration: var(--echo-duration-swap);
  transition-timing-function: ease-in;
}
/*
 * Flicked away: it carries on from where the finger let go, at the speed it
 * was thrown (--fling-ms), turning as it goes (--fling-turn), like a card
 * off ThrowStack. Both are set as the finger lifts (toast.tsx).
 */
.echo-toaster .echo-toast[data-ending-style][data-swipe-direction] {
  rotate: var(--fling-turn, 0deg);
  transition-duration: var(--fling-ms, var(--echo-duration-pop));
  transition-timing-function: cubic-bezier(0.2, 0.7, 0.4, 1);
}
.echo-toaster .echo-toast[data-ending-style][data-swipe-direction="right"] {
  transform: translateX(calc(var(--toast-swipe-movement-x, 0px) + 110%))
    translateY(var(--toast-swipe-movement-y, 0px));
}
.echo-toaster .echo-toast[data-ending-style][data-swipe-direction="left"] {
  transform: translateX(calc(var(--toast-swipe-movement-x, 0px) - 110%))
    translateY(var(--toast-swipe-movement-y, 0px));
}
.echo-toaster .echo-toast[data-ending-style][data-swipe-direction="down"] {
  transform: translateY(calc(var(--toast-swipe-movement-y, 0px) + 150%));
}

.echo-toast__text {
  flex: 1;
  min-width: 0;
}

.echo-toast__close {
  position: relative;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: var(--echo-radius-full);
  background: transparent;
  color: var(--echo-text-dim);
  cursor: pointer;
}
/* A 24px target around the 20px mark. */
.echo-toast__close::after {
  content: "";
  position: absolute;
  inset: -2px;
}
@media (hover: hover) {
  .echo-toast__close:hover {
    color: var(--echo-text);
  }
}
.echo-toast__close:focus-visible {
  outline: var(--echo-border-thick, 2px) solid var(--echo-accent-ink, var(--echo-accent-glow));
  outline-offset: 2px;
}
.echo-toast__close svg {
  width: var(--echo-icon-xs, 12px);
  height: var(--echo-icon-xs, 12px);
}

@media (prefers-reduced-motion: reduce) {
  .echo-toaster .echo-toast {
    transition: opacity var(--echo-duration-sweep) linear;
  }
  /* It still piles and fans, but jumps there; a flicked one fades where it is. */
  .echo-toaster .echo-toast[data-starting-style],
  .echo-toaster .echo-toast[data-ending-style] {
    transform: none;
    rotate: none;
    transition-duration: var(--echo-duration-sweep);
  }
  .echo-toaster .echo-toast[data-ending-style][data-swipe-direction] {
    transform: translate(var(--toast-swipe-movement-x, 0px), var(--toast-swipe-movement-y, 0px));
  }
}

"use client";

/**
 * Toast — a raised glass slab with a status LED, and
 * the toaster that announces it.
 *
 * Mount `<Toaster>` once around the app, then call `toast({ title })` from
 * `useToast()` anywhere inside it. The toaster's live region is on the page
 * before any message arrives. That's the point: a `role="status"` element
 * created at the same moment as its text is often not announced at all, which
 * is what the old Toast did. Base UI's Toast owns the queue, the timing, the
 * announcement and the keyboard (F6 moves focus into the toasts); Echo owns
 * the look.
 *
 * The toasts pile up like ThrowStack's cards, each one behind a step up and
 * a little smaller, and fan out into a column while the pointer or focus is
 * on them. Flick one away and it keeps the speed you gave it and spins from
 * where you held it (Base UI decides the swipe; Echo carries it on). The
 * dismiss button does the same for a keyboard.
 *
 * `Toast` on its own is the slab, for showing one on a page. It doesn't
 * announce anything.
 */
import { useRef, type HTMLAttributes, type PointerEvent, type ReactNode } from "react";
import { Toast as BaseToast } from "@base-ui/react/toast";
import type { EchoTone } from "echo-ui-core/types";
import { usePressable } from "echo-ui-core/tactile";
import "./toast.css";

/**
 * The subset of Echo's status vocabulary a toast expresses.
 *
 * This used to be `"default" | "active"` — a different vocabulary from
 * Banner's, using one of the same words for a different idea. `"default"`
 * is now `"info"`, which is what it always meant.
 *
 * A subset, not the whole list, for the same reason `size` is `"sm" | "md"`
 * on some components: a toast slab renders one LED, and `warn` and `danger`
 * have no distinct treatment on it yet. Accepting words it cannot express
 * would be a worse lie than not accepting them — a `danger` toast that
 * looked exactly like an `info` one is how a user misses the thing that
 * went wrong. Widening it is a design change, not a rename.
 */
export type ToastTone = Extract<EchoTone, "info" | "active">;

export interface ToastProps extends HTMLAttributes<HTMLDivElement> {
  title: string;
  body?: string;
  tone?: ToastTone;
}

/** The slab alone, for display. To announce something, use `useToast()`. */
export function Toast({ title, body, tone = "info", className, ...rest }: ToastProps) {
  return (
    <div className={["echo-toast", className].filter(Boolean).join(" ")} data-tone={tone} {...rest}>
      <span className="echo-toast__led" aria-hidden="true" />
      <div className="echo-toast__text">
        <span className="echo-toast__title">{title}</span>
        {body ? <span className="echo-toast__body">{body}</span> : null}
      </div>
    </div>
  );
}

export interface ToasterProps {
  children?: ReactNode;
  /** How long a toast stays, in ms. 0 keeps it until dismissed. Default 6000. */
  timeout?: number;
  /** How many show at once; older ones wait. Default 3. */
  limit?: number;
}

/** Mount once, around the app. Announces every toast from `useToast()` inside it. */
export function Toaster({ children, timeout = 6000, limit = 3 }: ToasterProps) {
  return (
    <BaseToast.Provider timeout={timeout} limit={limit}>
      {children}
      <BaseToast.Portal>
        <BaseToast.Viewport className="echo-toaster">
          <ToastList />
        </BaseToast.Viewport>
      </BaseToast.Portal>
    </BaseToast.Provider>
  );
}

function ToastList() {
  const { toasts } = BaseToast.useToastManager();
  const flick = useFlick();
  // Behind: not the front of the pile. One on its way out no longer counts.
  let shown = 0;
  const behind = new Set(toasts.filter((t) => t.transitionStatus !== "ending" && shown++ > 0).map((t) => t.id));
  // Oldest first, so the newest is painted last, on top of the pile.
  return [...toasts].reverse().map((t) => (
    <BaseToast.Root
      key={t.id}
      toast={t}
      className="echo-toast"
      data-tone={t.type === "active" ? "active" : "info"}
      data-behind={behind.has(t.id) ? "" : undefined}
      {...flick}
    >
      <span className="echo-toast__led" aria-hidden="true" />
      <div className="echo-toast__text">
        <BaseToast.Title className="echo-toast__title" />
        <BaseToast.Description className="echo-toast__body" />
      </div>
      {/*
        Base UI hides the close button from assistive tech until the stack is
        hovered or focused, which suits a collapsed pile of toasts. Echo's
        stack is a plain visible column, so hiding it only left a focusable
        button that a screen reader was told isn't there.
      */}
      <ToastCloseKey />
    </BaseToast.Root>
  ));
}

/**
 * ThrowStack's throw, on a toast. Base UI moves the toast with the finger and
 * decides whether it's dismissed; this adds what a thrown card does: it turns
 * as it's dragged (the other way when held low), and when it goes, it leaves
 * at the speed it was flicked (`--fling-ms`) and keeps turning
 * (`--fling-turn`). Under reduced motion it doesn't turn, and it leaves by
 * fading (toast.css).
 */
function useFlick() {
  const drag = useRef<{ x: number; y: number; flip: number; vx: number; vy: number; t: number; lx: number; ly: number } | null>(
    null,
  );
  const still = () => typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  return {
    onPointerDown(e: PointerEvent<HTMLDivElement>) {
      // Base UI doesn't swipe from a button; neither does the turn.
      if (e.button !== 0 || (e.target as Element).closest("button")) return;
      const r = e.currentTarget.getBoundingClientRect();
      drag.current = {
        x: e.clientX,
        y: e.clientY,
        flip: e.clientY > r.top + r.height / 2 ? -1 : 1,
        vx: 0,
        vy: 0,
        t: performance.now(),
        lx: e.clientX,
        ly: e.clientY,
      };
    },
    onPointerMove(e: PointerEvent<HTMLDivElement>) {
      const d = drag.current;
      if (!d) return;
      const now = performance.now();
      const dt = Math.max(1, now - d.t);
      d.vx = d.vx * 0.6 + ((e.clientX - d.lx) / dt) * 1000 * 0.4;
      d.vy = d.vy * 0.6 + ((e.clientY - d.ly) / dt) * 1000 * 0.4;
      d.lx = e.clientX;
      d.ly = e.clientY;
      d.t = now;
      if (!still()) e.currentTarget.style.rotate = `${((e.clientX - d.x) * 0.07 * d.flip).toFixed(2)}deg`;
    },
    onPointerUp(e: PointerEvent<HTMLDivElement>) {
      const d = drag.current;
      drag.current = null;
      const el = e.currentTarget;
      el.style.rotate = "";
      if (!d) return;
      // It leaves at the speed it was flicked: a slow push drifts off, a flick is gone.
      const speed = Math.hypot(d.vx, d.vy);
      const ms = Math.round(Math.min(320, Math.max(140, (el.offsetWidth / Math.max(speed, 1)) * 1000)));
      const sideways = Math.abs(e.clientX - d.x) >= Math.abs(e.clientY - d.y);
      el.style.setProperty("--fling-ms", `${ms}ms`);
      el.style.setProperty("--fling-turn", `${sideways ? Math.sign(e.clientX - d.x || 1) * 22 : d.flip * 8}deg`);
    },
    onPointerCancel(e: PointerEvent<HTMLDivElement>) {
      drag.current = null;
      e.currentTarget.style.rotate = "";
    },
  };
}

export interface ToastOptions {
  title: string;
  body?: string;
  /**
   * `active` lights the LED: for something happening, not for emphasis.
   * `info` (the default) is the plain slab.
   */
  tone?: ToastTone;
  /**
   * `high` interrupts what a screen reader is saying; keep it for things that
   * can't wait. Default `low`, announced politely.
   */
  priority?: "low" | "high";
  /** Override the toaster's timeout for this one, in ms. 0 keeps it until dismissed. */
  timeout?: number;
}

/** Returns `toast(options)`, which shows and announces a toast and returns its id. */
export function useToast() {
  const manager = BaseToast.useToastManager();
  return ({ title, body, tone = "info", priority, timeout }: ToastOptions): string =>
    manager.add({ title, description: body, type: tone, priority, timeout });
}

/* The dismiss key presses like the library's keys: a small one, 1px down. */
function ToastCloseKey() {
  const press = usePressable<HTMLButtonElement>({}, { lift: 0, travel: 1, tilt: 0 });
  return (
    <BaseToast.Close className="echo-toast__close" aria-label="Dismiss notification" aria-hidden={false} {...press}>
      <svg viewBox="0 0 12 12" aria-hidden="true" focusable="false">
        <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
      </svg>
    </BaseToast.Close>
  );
}
